func arr(v any)[]any { if x,ok:=v.([]any);ok{return x};return []any{} }
func str(v any)string{x,_:=v.(string);return x}
func has(xs []any,x string)bool{for _,v:=range xs{if str(v)==x{return true}};return false}
func audit(user map[string]any,role,action,entityType,entityID string,success bool,changes any){ db.Audit=append(db.Audit,map[string]any{"auditId":id(),"actorId":user["userId"],"role":role,"action":action,"entityType":entityType,"entityId":entityID,"occurredAt":now(),"success":success,"changes":changes}) }
func auth(w http.ResponseWriter,r *http.Request)(map[string]any,string,bool){ token:=strings.TrimPrefix(r.Header.Get("Authorization"),"Bearer "); uid:=db.Sessions[token]; u:=db.Users[uid]; if u==nil||!u["active"].(bool){err(w,401,"unauthorized","Authentication is required");return nil,"",false}; role:=r.Header.Get("X-Active-Role"); if role=="" { role=str(u["activeRole"])}; if role==""||!has(arr(u["roles"]),role){err(w,409,"role_not_selected","Select an assigned active role");return nil,"",false}; return u,role,true }
func require(w http.ResponseWriter,u map[string]any,role string, roles ...string)bool{for _,r:=range roles{if role==r{return true}};err(w,403,"forbidden","This role cannot perform this action");return false}
