func handoff(w http.ResponseWriter,u map[string]any,r string,x map[string]any,p string){if p=="initiate-handoff"{s:=db.Samples[str(x["sampleId"])];if s==nil{err(w,404,"not_found","Sample not found");return};if str(s["currentHolderId"])!=str(u["userId"]){err(w,403,"forbidden","Only current holder can initiate handoff");return};h:=map[string]any{"handoffId":id(),"sampleId":s["sampleId"],"senderId":u["userId"],"receiverId":x["receiverId"],"status":"pending","senderConfirmed":true,"receiverConfirmed":false};db.Handoffs[str(h["handoffId"])]=h;s["pendingHandoffId"]=h["handoffId"];write(w,201,map[string]any{"data":map[string]any{"handoffId":h["handoffId"],"sampleId":s["sampleId"],"status":"pending","currentHolderId":s["currentHolderId"]}});return};h:=db.Handoffs[str(x["handoffId"])];if h==nil{err(w,404,"not_found","Handoff not found");return};if str(x["confirmationSide"])=="receiver"&&str(h["receiverId"])==str(u["userId"]){h["receiverConfirmed"]=true};done,_:=h["senderConfirmed"].(bool);recv,_:=h["receiverConfirmed"].(bool);if done&&recv{h["status"]="completed";s:=db.Samples[str(h["sampleId"])];s["currentHolderId"]=h["receiverId"];delete(s,"pendingHandoffId")};write(w,201,map[string]any{"data":map[string]any{"handoffId":h["handoffId"],"status":h["status"],"currentHolderId":db.Samples[str(h["sampleId"])]["currentHolderId"]}})}
