func updateLocation(w http.ResponseWriter,a map[string]any,r string,x map[string]any){if !require(w,a,r,"administrator"){return};v:=db.Locations[str(x["locationId"])];if v==nil{err(w,404,"not_found","Location not found");return};for k,z:=range x{v[k]=z};write(w,200,map[string]any{"data":v})}
