func adminChange(w http.ResponseWriter,a map[string]any,r string,x map[string]any,p string){ if p=="configure-capacity" && (r=="node_handler"||r=="laboratory_intake_operator"){} else if !require(w,a,r,"administrator"){return};var v map[string]any; switch p{case "set-location-status":v=db.Locations[str(x["locationId"])];if v!=nil{v["active"]=x["active"]};case "set-location-function-status":v=db.Locations[str(x["locationId"])];if v!=nil{fs:=arr(v["functions"]);f:=str(x["function"]);on,_:=x["active"].(bool);if on&&!has(fs,f){fs=append(fs,f)};if !on{n:=[]any{};for _,q:=range fs{if str(q)!=f{n=append(n,q)}};fs=n};v["functions"]=fs};case "set-connection-status":v=db.Connections[str(x["connectionId"])];if v!=nil{v["active"]=x["active"]};case "configure-capacity":v=db.Locations[str(x["resourceId"])];if v==nil{v=db.Connections[str(x["resourceId"])]};if v!=nil{v["capacityUnits"]=x["capacityUnits"];v["cooledCapacityUnits"]=x["cooledCapacityUnits"]};case "configure-laboratory-acceptance":v=db.Locations[str(x["laboratoryId"])];if v!=nil{ss:=arr(v["acceptedSampleTypeIds"]);if b,_:=x["accepts"].(bool);b&&!has(ss,str(x["sampleTypeId"])) {ss=append(ss,x["sampleTypeId"])};v["acceptedSampleTypeIds"]=ss;write(w,200,map[string]any{"data":map[string]any{"acceptanceId":id(),"accepts":x["accepts"]}});return};case "set-worker-availability":v=db.Users[str(x["workerId"])];if v!=nil{v["available"]=x["available"];v["capacityUnits"]=x["capacityUnits"]}};if v==nil{err(w,404,"not_found","Resource not found");return};db.Revision++;write(w,200,map[string]any{"data":map[string]any{"resourceId":x["resourceId"],"capacityUnits":v["capacityUnits"],"cooledCapacityUnits":v["cooledCapacityUnits"]}})}
func check(w http.ResponseWriter,u map[string]any,r string,x map[string]any){ok,reason,lab:=service(x);d:=map[string]any{"serviceable":ok,"reason":reason,"serviceabilityVersion":db.Revision};if ok{d["targetLaboratoryId"]=lab["locationId"];d["estimatedArrivalAt"]=now()};write(w,200,map[string]any{"data":d})}
func snapshot(w http.ResponseWriter,u map[string]any,r string){regions:=[]any{};for _,l:=range db.Locations{if l["active"]==true&&has(arr(l["functions"]),"collection_point"){regions=append(regions,map[string]any{"locationId":l["locationId"],"coordinate":l["coordinate"],"coverageKm":l["coverageKm"]})}};write(w,200,map[string]any{"data":map[string]any{"version":db.Revision,"status":"complete","computedAt":now(),"networkRevision":db.Revision,"regions":regions,"activeCollectionPointCount":len(regions)}})}
func createRequest(w http.ResponseWriter,u map[string]any,r string,x map[string]any,presealed bool){if !require(w,u,r,"requester","certified_collection_professional","relay_courier","node_handler","laboratory_intake_operator"){return};if presealed&&str(x["originType"])=="home"{err(w,400,"invalid_origin","Pre-sealed samples cannot originate at a home");return};ok,reason,lab:=service(x);if !ok{err(w,409,reason,"The request is not serviceable");return};sid,rid,jid:=id(),id(),id();status:="planned";if presealed{status="sealed"};s:=map[string]any{"sampleId":sid,"requestId":rid,"requesterId":u["userId"],"origin":x["origin"],"originType":x["originType"],"requestedAt":x["requestedAt"],"deliveryDeadline":x["deliveryDeadline"],"earliestCollectionAt":x["earliestCollectionAt"],"latestCollectionAt":x["latestCollectionAt"],"sampleTypeId":x["sampleTypeId"],"containerType":x["containerType"],"temperatureMinC":x["temperatureMinC"],"temperatureMaxC":x["temperatureMaxC"],"incompatibleSampleTypes":arr(x["incompatibleSampleTypes"]),"serviceability":"serviceable","status":status,"sealed":presealed,"timeline":timeline(status),"activeJourneyId":jid,"targetLaboratoryId":lab["locationId"],"locationStale":false};if presealed{s["currentHolderId"]=u["userId"]};db.Samples[sid]=s;j:=map[string]any{"journeyId":jid,"sampleIds":[]any{sid},"status":"active","routeMode":"direct","planVersion":1,"targetLaboratoryId":lab["locationId"],"estimatedDeliveryAt":x["deliveryDeadline"],"legs":[]any{},"history":timeline("planned")};db.Journeys[jid]=j;kind:="collection";if presealed{kind="transport"};aid:=id();a:=map[string]any{"assignmentId":aid,"sampleId":sid,"journeyId":jid,"kind":kind,"status":"offered","sequence":1,"toLocationId":lab["locationId"],"history":timeline("offered")};db.Assignments[aid]=a;s["activeAssignmentIds"]=[]any{aid};audit(u,r,"create_request","sample",sid,true,s);write(w,201,map[string]any{"data":map[string]any{"requestId":rid,"sampleId":sid,"journeyId":jid,"serviceability":"serviceable","status":status,"targetLaboratoryId":lab["locationId"]}})}
func roleWork(w http.ResponseWriter,u map[string]any,r string,x map[string]any){out:=map[string]any{"pending":[]any{},"inProgress":[]any{},"completed":[]any{}};if r=="requester"{for _,s:=range db.Samples{if str(s["requesterId"])==str(u["userId"]){bucket:="inProgress";if str(s["status"])=="received"{bucket="completed"};out[bucket]=append(arr(out[bucket]),sampleItem(s))}}}else{for _,a:=range db.Assignments{if str(a["workerId"])==str(u["userId"]){bucket:="pending";if str(a["status"])=="accepted"||str(a["status"])=="in_progress"{bucket="inProgress"};if str(a["status"])=="completed"{bucket="completed"};out[bucket]=append(arr(out[bucket]),assignmentItem(a))}}};write(w,200,map[string]any{"data":out})}
func sampleItem(s map[string]any)map[string]any{return map[string]any{"kind":"sample","sampleId":s["sampleId"],"requestId":s["requestId"],"status":s["status"],"history":s["timeline"],"locationStale":s["locationStale"],"deliveryDeadline":s["deliveryDeadline"],"currentHolderId":s["currentHolderId"],"activeJourneyId":s["activeJourneyId"]}}
func assignmentItem(a map[string]any)map[string]any{return map[string]any{"kind":a["kind"],"assignmentId":a["assignmentId"],"sampleId":a["sampleId"],"status":a["status"],"history":a["history"],"journeyId":a["journeyId"],"sequence":a["sequence"],"toLocationId":a["toLocationId"]}}
func sampleState(w http.ResponseWriter,u map[string]any,r,sid string){s:=db.Samples[sid];if s==nil{err(w,404,"not_found","Sample not found");return};if r=="requester"&&str(s["requesterId"])!=str(u["userId"]){err(w,403,"forbidden","Sample is not yours");return};d:=map[string]any{"sampleId":s["sampleId"],"requestId":s["requestId"],"requesterId":s["requesterId"],"origin":s["origin"],"originType":s["originType"],"requestedAt":s["requestedAt"],"deliveryDeadline":s["deliveryDeadline"],"sampleTypeId":s["sampleTypeId"],"containerType":s["containerType"],"temperatureMinC":s["temperatureMinC"],"temperatureMaxC":s["temperatureMaxC"],"incompatibleSampleTypes":s["incompatibleSampleTypes"],"serviceability":s["serviceability"],"activeAssignmentIds":s["activeAssignmentIds"],"state":map[string]any{"status":s["status"]},"timeline":s["timeline"],"activeJourneyId":s["activeJourneyId"],"targetLaboratoryId":s["targetLaboratoryId"],"currentHolderId":s["currentHolderId"],"latestLocation":s["latestLocation"],"locationRecordedAt":s["locationRecordedAt"],"locationStale":s["locationStale"]};for k,v:=range d{if v==nil{delete(d,k)}};write(w,200,map[string]any{"data":d})}
func lifecycle(w http.ResponseWriter,u map[string]any,r string,x map[string]any){s:=db.Samples[str(x["sampleId"])];if s==nil{err(w,404,"not_found","Sample not found");return};d:=map[string]any{"sampleId":s["sampleId"],"status":s["status"],"sealed":s["sealed"],"completedLegIds":[]any{},"activeReplacementPlanIds":[]any{},"timeline":s["timeline"],"activeJourneyId":s["activeJourneyId"],"currentHolderId":s["currentHolderId"],"pendingHandoffId":s["pendingHandoffId"],"latestLocation":s["latestLocation"],"locationRecordedAt":s["locationRecordedAt"],"locationStale":s["locationStale"]};for k,v:=range d{if v==nil{delete(d,k)}};write(w,200,map[string]any{"data":d})}
