func assignmentAction(w http.ResponseWriter,u map[string]any,r string,x map[string]any,p string){a:=db.Assignments[str(x["assignmentId"])];if a==nil{err(w,404,"not_found","Assignment not found");return};if p=="accept-assignment"{if str(a["status"])!="offered"{err(w,409,"offer_not_available","Assignment offer is no longer available");return};a["workerId"]=u["userId"];a["status"]="accepted";write(w,201,map[string]any{"data":map[string]any{"assignmentId":a["assignmentId"],"workerId":u["userId"],"status":"accepted"}});return};if str(a["workerId"])!=str(u["userId"]){err(w,403,"forbidden","Assignment belongs to another worker");return};if p=="decline-assignment"{a["status"]="declined";write(w,201,map[string]any{"data":map[string]any{"assignmentId":a["assignmentId"],"status":"declined"}});return};if p=="record-worker-location"{a["latestLocation"]=x["coordinate"];a["locationRecordedAt"]=x["recordedAt"];write(w,201,map[string]any{"data":map[string]any{"assignmentId":a["assignmentId"],"coordinate":x["coordinate"],"sequence":x["sequence"],"recordedAt":x["recordedAt"]}});return};a["status"]=x["status"];a["history"]=append(arr(a["history"]),map[string]any{"status":x["status"],"occurredAt":x["occurredAt"]});write(w,201,map[string]any{"data":map[string]any{"assignmentId":a["assignmentId"],"status":a["status"]}})}
func seal(w http.ResponseWriter,u map[string]any,r string,x map[string]any){if !require(w,u,r,"certified_collection_professional"){return};s:=db.Samples[str(x["sampleId"])];a:=db.Assignments[str(x["assignmentId"])];if s==nil||a==nil{err(w,404,"not_found","Sample or assignment not found");return};if str(a["workerId"])!=str(u["userId"])||str(a["status"])!="accepted"{err(w,409,"collection_not_ready","Accept the collection assignment first");return};s["sealed"]=true;s["status"]="sealed";s["currentHolderId"]=u["userId"];s["sealedAt"]=x["collectedAt"];s["timeline"]=append(arr(s["timeline"]),map[string]any{"status":"sealed","occurredAt":x["collectedAt"]});a["status"]="completed";write(w,201,map[string]any{"data":map[string]any{"sampleId":s["sampleId"],"status":"sealed","currentHolderId":u["userId"],"sealedAt":x["collectedAt"],"handlingCompliant":true}})}

