func createRequest(w http.ResponseWriter, u map[string]any, r string, x map[string]any, presealed bool) {
	if !require(w, u, r, "requester", "certified_collection_professional", "relay_courier", "node_handler", "laboratory_intake_operator") {
		return
	}
	if presealed && str(x["originType"]) == "home" {
		err(w, 400, "invalid_origin", "Pre-sealed samples cannot originate at a home")
		return
	}
	ok, reason, lab := service(x)
	if !ok {
		err(w, 409, reason, "The request is not serviceable")
		return
	}
	sid, rid, jid := id(), id(), id()
	status := "planned"
	if presealed {
		status = "sealed"
	}
	s := map[string]any{"sampleId": sid, "requestId": rid, "requesterId": u["userId"], "origin": x["origin"], "originType": x["originType"], "requestedAt": x["requestedAt"], "deliveryDeadline": x["deliveryDeadline"], "earliestCollectionAt": x["earliestCollectionAt"], "latestCollectionAt": x["latestCollectionAt"], "sampleTypeId": x["sampleTypeId"], "containerType": x["containerType"], "temperatureMinC": x["temperatureMinC"], "temperatureMaxC": x["temperatureMaxC"], "incompatibleSampleTypes": arr(x["incompatibleSampleTypes"]), "serviceability": "serviceable", "status": status, "sealed": presealed, "timeline": timeline(status), "activeJourneyId": jid, "targetLaboratoryId": lab["locationId"], "locationStale": false}
	if presealed {
		s["currentHolderId"] = u["userId"]
	}
	db.Samples[sid] = s
	j := map[string]any{"journeyId": jid, "sampleIds": []any{sid}, "status": "active", "routeMode": "direct", "planVersion": 1, "targetLaboratoryId": lab["locationId"], "estimatedDeliveryAt": x["deliveryDeadline"], "legs": []any{}, "history": timeline("planned")}
	db.Journeys[jid] = j
	kind := "collection"
	if presealed {
		kind = "transport"
	}
	aid := id()
	a := map[string]any{"assignmentId": aid, "sampleId": sid, "journeyId": jid, "kind": kind, "status": "offered", "sequence": 1, "toLocationId": lab["locationId"], "history": timeline("offered")}
	db.Assignments[aid] = a
	s["activeAssignmentIds"] = []any{aid}
	audit(u, r, "create_request", "sample", sid, true, s)
	write(w, 201, map[string]any{"data": map[string]any{"requestId": rid, "sampleId": sid, "journeyId": jid, "serviceability": "serviceable", "status": status, "targetLaboratoryId": lab["locationId"]}})
}
func roleWork(w http.ResponseWriter, u map[string]any, r string, x map[string]any) {
	out := map[string]any{"pending": []any{}, "inProgress": []any{}, "completed": []any{}}
	if r == "requester" {
		for _, s := range db.Samples {
			if str(s["requesterId"]) == str(u["userId"]) {
				bucket := "inProgress"
				if str(s["status"]) == "received" {
					bucket = "completed"
				}
				out[bucket] = append(arr(out[bucket]), sampleItem(s))
			}
		}
	} else {
		for _, a := range db.Assignments {
			if str(a["workerId"]) == str(u["userId"]) {
				bucket := "pending"
				if str(a["status"]) == "accepted" || str(a["status"]) == "in_progress" {
					bucket = "inProgress"
				}
				if str(a["status"]) == "completed" {
					bucket = "completed"
				}
				out[bucket] = append(arr(out[bucket]), assignmentItem(a))
			}
		}
	}
	write(w, 200, map[string]any{"data": out})
}
