func assignmentAction(w http.ResponseWriter, u map[string]any, r string, x map[string]any, p string) {
	a := db.Assignments[str(x["assignmentId"])]
	if a == nil {
		err(w, 404, "not_found", "Assignment not found")
		return
	}
	if p == "accept-assignment" {
		if str(a["status"]) != "offered" {
			err(w, 409, "offer_not_available", "Assignment offer is no longer available")
			return
		}
		a["workerId"] = u["userId"]
		a["status"] = "accepted"
		write(w, 201, map[string]any{"data": map[string]any{"assignmentId": a["assignmentId"], "workerId": u["userId"], "status": "accepted"}})
		return
	}
	if str(a["workerId"]) != str(u["userId"]) {
		err(w, 403, "forbidden", "Assignment belongs to another worker")
		return
	}
	if p == "decline-assignment" {
		a["status"] = "declined"
		write(w, 201, map[string]any{"data": map[string]any{"assignmentId": a["assignmentId"], "status": "declined"}})
		return
	}
	if p == "record-worker-location" {
		a["latestLocation"] = x["coordinate"]
		a["locationRecordedAt"] = x["recordedAt"]
		write(w, 201, map[string]any{"data": map[string]any{"assignmentId": a["assignmentId"], "coordinate": x["coordinate"], "sequence": x["sequence"], "recordedAt": x["recordedAt"]}})
		return
	}
	a["status"] = x["status"]
	a["history"] = append(arr(a["history"]), map[string]any{"status": x["status"], "occurredAt": x["occurredAt"]})
	write(w, 201, map[string]any{"data": map[string]any{"assignmentId": a["assignmentId"], "status": a["status"]}})
}
func seal(w http.ResponseWriter, u map[string]any, r string, x map[string]any) {
	if !require(w, u, r, "collection_professional") {
		return
	}
	s := db.Samples[str(x["sampleId"])]
	a := db.Assignments[str(x["assignmentId"])]
	if s == nil || a == nil {
		err(w, 404, "not_found", "Sample or assignment not found")
		return
	}
	if str(a["workerId"]) != str(u["userId"]) || str(a["status"]) != "accepted" {
		err(w, 409, "collection_not_ready", "Accept the collection assignment first")
		return
	}
	s["sealed"] = true
	s["status"] = "sealed"
	s["currentHolderId"] = u["userId"]
	s["sealedAt"] = x["collectedAt"]
	s["timeline"] = append(arr(s["timeline"]), map[string]any{"status": "sealed", "occurredAt": x["collectedAt"]})
	a["status"] = "completed"
	write(w, 201, map[string]any{"data": map[string]any{"sampleId": s["sampleId"], "status": "sealed", "currentHolderId": u["userId"], "sealedAt": x["collectedAt"], "handlingCompliant": true}})
}
func handoff(w http.ResponseWriter, u map[string]any, r string, x map[string]any, p string) {
	if p == "initiate-handoff" {
		s := db.Samples[str(x["sampleId"])]
		if s == nil {
			err(w, 404, "not_found", "Sample not found")
			return
		}
		if str(s["currentHolderId"]) != str(u["userId"]) {
			err(w, 403, "forbidden", "Only current holder can initiate handoff")
			return
		}
		h := map[string]any{"handoffId": id(), "sampleId": s["sampleId"], "senderId": u["userId"], "receiverId": x["receiverId"], "status": "pending", "senderConfirmed": true, "receiverConfirmed": false}
		db.Handoffs[str(h["handoffId"])] = h
		s["pendingHandoffId"] = h["handoffId"]
		write(w, 201, map[string]any{"data": map[string]any{"handoffId": h["handoffId"], "sampleId": s["sampleId"], "status": "pending", "currentHolderId": s["currentHolderId"]}})
		return
	}
	h := db.Handoffs[str(x["handoffId"])]
	if h == nil {
		err(w, 404, "not_found", "Handoff not found")
		return
	}
	if str(x["confirmationSide"]) == "receiver" && str(h["receiverId"]) == str(u["userId"]) {
		h["receiverConfirmed"] = true
	}
	done, _ := h["senderConfirmed"].(bool)
	recv, _ := h["receiverConfirmed"].(bool)
	if done && recv {
		h["status"] = "completed"
		s := db.Samples[str(h["sampleId"])]
		s["currentHolderId"] = h["receiverId"]
		delete(s, "pendingHandoffId")
	}
	write(w, 201, map[string]any{"data": map[string]any{"handoffId": h["handoffId"], "status": h["status"], "currentHolderId": db.Samples[str(h["sampleId"])]["currentHolderId"]}})
}
func sampleAction(w http.ResponseWriter, u map[string]any, r string, x map[string]any, p string) {
	s := db.Samples[str(x["sampleId"])]
	if s == nil {
		err(w, 404, "not_found", "Sample not found")
		return
	}
	if p == "confirm-laboratory-receipt" {
		if !require(w, u, r, "laboratory_team") {
			return
		}
		s["status"] = "received"
		s["receivedLaboratoryId"] = x["laboratoryId"]
		s["timeline"] = append(arr(s["timeline"]), map[string]any{"status": "received", "occurredAt": x["receivedAt"]})
		write(w, 201, map[string]any{"data": map[string]any{"sampleId": s["sampleId"], "status": "received", "receivedAt": x["receivedAt"], "laboratoryId": x["laboratoryId"]}})
		return
	}
	if p == "record-laboratory-exception" {
		s["status"] = "exception"
		write(w, 201, map[string]any{"data": map[string]any{"exceptionId": id(), "sampleId": s["sampleId"], "status": "exception", "reason": x["reason"]}})
		return
	}
	lo, _ := x["observedTemperatureC"].(float64)
	min, _ := s["temperatureMinC"].(float64)
	max, _ := s["temperatureMaxC"].(float64)
	good := lo >= min && lo <= max && str(x["containerType"]) == str(s["containerType"])
	if !good {
		s["status"] = "exception"
	}
	write(w, 201, map[string]any{"data": map[string]any{"checkpointId": id(), "sampleId": s["sampleId"], "compliant": good, "sampleStatus": s["status"]}})
}
func operations(w http.ResponseWriter, u map[string]any, r string) {
	if !require(w, u, r, "dispatcher", "administrator") {
		return
	}
	ss, ws, ls, cs, ex := []any{}, []any{}, []any{}, []any{}, []any{}
	for _, s := range db.Samples {
		ss = append(ss, map[string]any{"sampleId": s["sampleId"], "status": s["status"], "locationStale": s["locationStale"]})
		if str(s["status"]) == "exception" {
			ex = append(ex, s)
		}
	}
	for _, v := range db.Users {
		ws = append(ws, map[string]any{"workerId": v["userId"], "available": v["available"], "status": "available", "capacityUnits": v["capacityUnits"], "assignmentCount": 0, "locationStale": false})
	}
	for _, v := range db.Locations {
		ls = append(ls, v)
	}
	for _, v := range db.Connections {
		cs = append(cs, v)
	}
	write(w, 200, map[string]any{"data": map[string]any{"samples": ss, "workers": ws, "locations": ls, "connections": cs, "routes": []any{}, "handoffs": []any{}, "delays": []any{}, "exceptions": ex, "assignmentCountSpread": 0, "ineligibleAssignmentCount": 0}})
}
func searchAudit(w http.ResponseWriter, u map[string]any, r string, x map[string]any) {
	if !require(w, u, r, "dispatcher", "administrator") {
		return
	}
	out := []any{}
	for _, v := range db.Audit {
		out = append(out, v)
	}
	sort.Slice(out, func(i, j int) bool {
		return str(out[i].(map[string]any)["occurredAt"]) > str(out[j].(map[string]any)["occurredAt"])
	})
	write(w, 200, map[string]any{"data": map[string]any{"entries": out, "total": len(out), "returned": len(out), "offset": 0, "limit": len(out), "order": "newest_first", "hasMore": false}})
