package main

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"math"
	"net/http"
	"os"
	"sort"
	"strings"
	"sync"
	"time"
)

type Store struct {
	sync.Mutex
	Users       map[string]map[string]any `json:"users"`
	Sessions    map[string]string         `json:"sessions"`
	Locations   map[string]map[string]any `json:"locations"`
	Connections map[string]map[string]any `json:"connections"`
	Types       map[string]map[string]any `json:"types"`
	Samples     map[string]map[string]any `json:"samples"`
	Journeys    map[string]map[string]any `json:"journeys"`
	Assignments map[string]map[string]any `json:"assignments"`
	Handoffs    map[string]map[string]any `json:"handoffs"`
	Audit       []map[string]any          `json:"audit"`
	Revision    int                       `json:"revision"`
}

var db = &Store{}
var stateFile = "/workspace/.labflow-state.json"

func id() string {
	b := make([]byte, 16)
	rand.Read(b)
	return fmt.Sprintf("%s-%s-4%s-%s-%s", hex.EncodeToString(b[:4]), hex.EncodeToString(b[4:6]), hex.EncodeToString(b[6:8])[:3], hex.EncodeToString(b[8:10]), hex.EncodeToString(b[10:]))
}
func now() string { return time.Now().UTC().Format(time.RFC3339) }
func initStore() {
	db.Users = map[string]map[string]any{}
	db.Sessions = map[string]string{}
	db.Locations = map[string]map[string]any{}
	db.Connections = map[string]map[string]any{}
	db.Types = map[string]map[string]any{}
	db.Samples = map[string]map[string]any{}
	db.Journeys = map[string]map[string]any{}
	db.Assignments = map[string]map[string]any{}
	db.Handoffs = map[string]map[string]any{}
	db.Audit = []map[string]any{}
	db.Revision = 1
}
func load() {
	initStore()
	b, e := os.ReadFile(stateFile)
	if e == nil {
		json.Unmarshal(b, db)
	}
	if len(db.Users) == 0 {
		u := map[string]any{"userId": id(), "username": os.Getenv("ADMIN_USERNAME"), "password": os.Getenv("ADMIN_PASSWORD"), "roles": []any{"administrator", "dispatcher"}, "qualifications": []any{}, "certifications": []any{}, "active": true, "available": true, "capacityUnits": 10}
		if u["username"] == "" {
			u["username"] = "admin"
		}
		if u["password"] == "" {
			u["password"] = "admin"
		}
		db.Users[u["userId"].(string)] = u
	}
	seedTypes()
}
func seedTypes() {
	if len(db.Types) > 0 {
		return
	}
	for _, v := range []struct {
		name, container string
		min, max        float64
		cool, batch     bool
	}{{"Amber", "standard", 2, 25, false, true}, {"Indigo", "indigo", 2, 25, false, true}, {"Frost", "cooled", 2, 8, true, true}, {"Pulse", "priority", 2, 25, false, false}} {
		x := map[string]any{"sampleTypeId": id(), "name": v.name, "qualifiedCollectorRequired": true, "requiredQualification": v.name, "containerType": v.container, "temperatureMinC": v.min, "temperatureMaxC": v.max, "incompatibleSampleTypes": []any{}, "requiresCooledRoute": v.cool, "batchingAllowed": v.batch}
		db.Types[x["sampleTypeId"].(string)] = x
	}
}
func save() { b, _ := json.Marshal(db); os.WriteFile(stateFile, b, 0600) }
func write(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}
func err(w http.ResponseWriter, status int, code, msg string) {
	write(w, status, map[string]any{"error": msg, "code": code})
}
func body(r *http.Request) (map[string]any, bool) {
	var x map[string]any
	if json.NewDecoder(r.Body).Decode(&x) != nil {
		return nil, false
	}
	return x, true
}
func arr(v any) []any {
	if x, ok := v.([]any); ok {
		return x
	}
	return []any{}
}
func str(v any) string { x, _ := v.(string); return x }
func has(xs []any, x string) bool {
	for _, v := range xs {
		if str(v) == x {
			return true
		}
	}
	return false
}
func audit(user map[string]any, role, action, entityType, entityID string, success bool, changes any) {
	db.Audit = append(db.Audit, map[string]any{"auditId": id(), "actorId": user["userId"], "role": role, "action": action, "entityType": entityType, "entityId": entityID, "occurredAt": now(), "success": success, "changes": changes})
}
func auth(w http.ResponseWriter, r *http.Request) (map[string]any, string, bool) {
	token := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
	uid := db.Sessions[token]
	u := db.Users[uid]
	if u == nil || !u["active"].(bool) {
		err(w, 401, "unauthorized", "Authentication is required")
		return nil, "", false
	}
	role := r.Header.Get("X-Active-Role")
	if role == "" {
		role = str(u["activeRole"])
	}
	if role == "" || !has(arr(u["roles"]), role) {
		err(w, 409, "role_not_selected", "Select an assigned active role")
		return nil, "", false
	}
	return u, role, true
}
func require(w http.ResponseWriter, u map[string]any, role string, roles ...string) bool {
	for _, r := range roles {
		if role == r {
			return true
		}
	}
	err(w, 403, "forbidden", "This role cannot perform this action")
	return false
}
func timeline(status string) []any {
	return []any{map[string]any{"status": status, "occurredAt": now()}}
}
func coord(v any) map[string]any { x, _ := v.(map[string]any); return x }
func distance(a, b map[string]any) float64 {
	lat1, _ := a["latitude"].(float64)
	lon1, _ := a["longitude"].(float64)
	lat2, _ := b["latitude"].(float64)
	lon2, _ := b["longitude"].(float64)
	return math.Hypot((lat1-lat2)*111, (lon1-lon2)*75)
}
func acceptingLab(typeID string) (map[string]any, bool) {
	for _, l := range db.Locations {
		if l["active"] == true && has(arr(l["functions"]), "laboratory") && has(arr(l["acceptedSampleTypeIds"]), typeID) {
			return l, true
		}
	}
	return nil, false
}
func activeCollection(origin map[string]any) bool {
	for _, l := range db.Locations {
		if l["active"] == true && has(arr(l["functions"]), "collection_point") && distance(origin, coord(l["coordinate"])) <= 5 {
			return true
		}
	}
	return false
}
func service(x map[string]any) (bool, string, map[string]any) {
	if !activeCollection(coord(x["origin"])) {
		return false, "outside_service_coverage", nil
	}
	l, ok := acceptingLab(str(x["sampleTypeId"]))
	if !ok {
		return false, "no_accepting_laboratory", nil
	}
	return true, "serviceable", l
}
func main() {
	load()
	if len(os.Args) > 1 && os.Args[1] == "--reset" {
		save()
		return
	}
	defer save()
	mux := http.NewServeMux()
	mux.HandleFunc("/ready", func(w http.ResponseWriter, r *http.Request) { write(w, 200, map[string]string{"status": "ready"}) })
	mux.HandleFunc("/api/", api)
	mux.HandleFunc("/", web)
	log.Println("LabFlow listening at 127.0.0.1:8080")
	log.Fatal(http.ListenAndServe("127.0.0.1:8080", mux))
}
func web(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Write([]byte(indexHTML))
}
func api(w http.ResponseWriter, r *http.Request) {
	db.Lock()
	defer db.Unlock()
	p := strings.TrimPrefix(r.URL.Path, "/api/")
	if p == "authenticate-user" {
		login(w, r)
		return
	}
	if p == "events" {
		w.Header().Set("Content-Type", "text/event-stream")
		fmt.Fprint(w, "event: ready\ndata: {\"status\":\"connected\"}\n\n")
		return
	}
	u, role, ok := auth(w, r)
	if !ok {
		return
	}
	if p == "ui/bootstrap" && r.Method == "GET" {
		bootstrap(w, u, role)
		return
	}
	if strings.HasPrefix(p, "read-sample-state/") {
		sampleState(w, u, role, strings.TrimPrefix(p, "read-sample-state/"))
		return
	}
	if strings.HasPrefix(p, "read-user/") {
		readUser(w, u, role, strings.TrimPrefix(p, "read-user/"))
		return
	}
	x, valid := body(r)
	if !valid {
		err(w, 400, "invalid_json", "Invalid JSON body")
		return
	}
	switch p {
	case "select-active-role":
		selectRole(w, u, x)
	case "create-user":
		createUser(w, u, role, x)
	case "update-user-access":
		updateUser(w, u, role, x)
	case "create-sample-type":
		createType(w, u, role, x)
	case "update-sample-type":
		updateType(w, u, role, x)
	case "create-location":
		createLocation(w, u, role, x)
	case "update-location":
		updateLocation(w, u, role, x)
	case "create-connection":
		createConnection(w, u, role, x)
	case "set-location-status", "set-location-function-status", "set-connection-status", "configure-capacity", "configure-laboratory-acceptance", "set-worker-availability":
		adminChange(w, u, role, x, p)
	case "check-serviceability":
		check(w, u, role, x)
	case "read-serviceability-snapshot":
		snapshot(w, u, role)
	case "create-collection-request", "ingest-presealed-sample":
		createRequest(w, u, role, x, p == "ingest-presealed-sample")
	case "list-role-work":
		roleWork(w, u, role, x)
	case "read-sample-lifecycle":
		lifecycle(w, u, role, x)
	case "read-operations-state":
		operations(w, u, role)
	case "read-journey-plan":
		plan(w, u, role, x)
	case "accept-assignment", "decline-assignment", "update-assignment-progress", "record-worker-location":
		assignmentAction(w, u, role, x, p)
	case "collect-and-seal-sample":
		seal(w, u, role, x)
	case "initiate-handoff", "confirm-handoff":
		handoff(w, u, role, x, p)
	case "confirm-laboratory-receipt", "record-laboratory-exception", "record-handling-checkpoint":
		sampleAction(w, u, role, x, p)
	case "search-audit-trail":
		searchAudit(w, u, role, x)
	case "cancel-journey", "reroute-journey", "split-journey", "merge-journeys", "edit-active-plan", "report-disruption":
		planChange(w, u, role, x, p)
	default:
		err(w, 404, "not_found", "Unknown API operation")
	}
	save()
}
func login(w http.ResponseWriter, r *http.Request) {
	x, ok := body(r)
	if !ok {
		err(w, 400, "invalid_json", "Invalid JSON body")
		return
	}
	for _, u := range db.Users {
		if str(u["username"]) == str(x["username"]) && str(u["password"]) == str(x["password"]) && u["active"] == true {
			t := id()
			db.Sessions[t] = str(u["userId"])
			roles := arr(u["roles"])
			active := str(u["activeRole"])
			if active == "" {
				active = str(roles[0])
				u["activeRole"] = active
			}
			audit(u, active, "sign_in", "user", str(u["userId"]), true, nil)
			write(w, 200, map[string]any{"data": map[string]any{"sessionToken": t, "userId": u["userId"], "roles": roles, "activeRole": active}})
			return
		}
	}
	err(w, 401, "invalid_credentials", "Username or password is incorrect")
}
func selectRole(w http.ResponseWriter, u map[string]any, x map[string]any) {
	r := str(x["role"])
	if !has(arr(u["roles"]), r) {
		err(w, 403, "forbidden", "Role is not assigned")
		return
	}
	u["activeRole"] = r
	write(w, 200, map[string]any{"data": map[string]any{"userId": u["userId"], "activeRole": r}})
}
func createUser(w http.ResponseWriter, actor map[string]any, role string, x map[string]any) {
	if !require(w, actor, role, "administrator") {
		return
	}
	for _, u := range db.Users {
		if str(u["username"]) == str(x["username"]) {
			err(w, 409, "conflict", "Username already exists")
			return
		}
	}
	v := map[string]any{"userId": id(), "username": x["username"], "password": x["initialPassword"], "roles": arr(x["roles"]), "qualifications": arr(x["qualifications"]), "certifications": arr(x["certifications"]), "active": x["active"], "email": x["email"], "fullName": x["fullName"], "phone": x["phone"], "assignedLocationId": x["assignedLocationId"], "available": true, "capacityUnits": 10}
	db.Users[str(v["userId"])] = v
	audit(actor, role, "create_user", "user", str(v["userId"]), true, v)
	write(w, 201, map[string]any{"data": map[string]any{"userId": v["userId"], "username": v["username"]}})
}
func updateUser(w http.ResponseWriter, a map[string]any, r string, x map[string]any) {
	if !require(w, a, r, "administrator") {
		return
	}
	u := db.Users[str(x["userId"])]
	if u == nil {
		err(w, 404, "not_found", "User not found")
		return
	}
	for _, k := range []string{"roles", "qualifications", "certifications", "active", "assignedLocationId"} {
		if v, ok := x[k]; ok {
			u[k] = v
		}
	}
	write(w, 200, map[string]any{"data": map[string]any{"userId": u["userId"], "roles": u["roles"], "active": u["active"]}})
}
func createType(w http.ResponseWriter, a map[string]any, r string, x map[string]any) {
	if !require(w, a, r, "administrator") {
		return
	}
	x["sampleTypeId"] = id()
	db.Types[str(x["sampleTypeId"])] = x
	write(w, 201, map[string]any{"data": x})
}
func updateType(w http.ResponseWriter, a map[string]any, r string, x map[string]any) {
	if !require(w, a, r, "administrator") {
		return
	}
	v := db.Types[str(x["sampleTypeId"])]
	if v == nil {
		err(w, 404, "not_found", "Sample type not found")
		return
	}
	for k, z := range x {
		v[k] = z
	}
	write(w, 200, map[string]any{"data": v})
}
func createLocation(w http.ResponseWriter, a map[string]any, r string, x map[string]any) {
	if !require(w, a, r, "administrator") {
		return
	}
	x["locationId"] = id()
	x["capacityUnits"] = float64(0)
	x["cooledCapacityUnits"] = float64(0)
	x["acceptedSampleTypeIds"] = []any{}
	db.Locations[str(x["locationId"])] = x
	write(w, 201, map[string]any{"data": x})
}
func updateLocation(w http.ResponseWriter, a map[string]any, r string, x map[string]any) {
	if !require(w, a, r, "administrator") {
		return
	}
	v := db.Locations[str(x["locationId"])]
	if v == nil {
		err(w, 404, "not_found", "Location not found")
		return
	}
	for k, z := range x {
		v[k] = z
	}
	write(w, 200, map[string]any{"data": v})
}
func createConnection(w http.ResponseWriter, a map[string]any, r string, x map[string]any) {
	if !require(w, a, r, "administrator") {
		return
	}
	x["connectionId"] = id()
	x["capacityUnits"] = float64(0)
	x["cooledCapacityUnits"] = float64(0)
	db.Connections[str(x["connectionId"])] = x
	write(w, 201, map[string]any{"data": x})
}
func adminChange(w http.ResponseWriter, a map[string]any, r string, x map[string]any, p string) {
	if p == "configure-capacity" && (r == "node_handler" || r == "laboratory_team") {
	} else if !require(w, a, r, "administrator") {
		return
	}
	var v map[string]any
	switch p {
	case "set-location-status":
		v = db.Locations[str(x["locationId"])]
		if v != nil {
			v["active"] = x["active"]
		}
	case "set-location-function-status":
		v = db.Locations[str(x["locationId"])]
		if v != nil {
			fs := arr(v["functions"])
			f := str(x["function"])
			on, _ := x["active"].(bool)
			if on && !has(fs, f) {
				fs = append(fs, f)
			}
			if !on {
				n := []any{}
				for _, q := range fs {
					if str(q) != f {
						n = append(n, q)
					}
				}
				fs = n
			}
			v["functions"] = fs
		}
	case "set-connection-status":
		v = db.Connections[str(x["connectionId"])]
		if v != nil {
			v["active"] = x["active"]
		}
	case "configure-capacity":
		v = db.Locations[str(x["resourceId"])]
		if v == nil {
			v = db.Connections[str(x["resourceId"])]
		}
		if v != nil {
			v["capacityUnits"] = x["capacityUnits"]
			v["cooledCapacityUnits"] = x["cooledCapacityUnits"]
		}
	case "configure-laboratory-acceptance":
		v = db.Locations[str(x["laboratoryId"])]
		if v != nil {
			ss := arr(v["acceptedSampleTypeIds"])
			if b, _ := x["accepts"].(bool); b && !has(ss, str(x["sampleTypeId"])) {
				ss = append(ss, x["sampleTypeId"])
			}
			v["acceptedSampleTypeIds"] = ss
			write(w, 200, map[string]any{"data": map[string]any{"acceptanceId": id(), "accepts": x["accepts"]}})
			return
		}
	case "set-worker-availability":
		v = db.Users[str(x["workerId"])]
		if v != nil {
			v["available"] = x["available"]
			v["capacityUnits"] = x["capacityUnits"]
		}
	}
	if v == nil {
		err(w, 404, "not_found", "Resource not found")
		return
	}
	db.Revision++
	write(w, 200, map[string]any{"data": map[string]any{"resourceId": x["resourceId"], "capacityUnits": v["capacityUnits"], "cooledCapacityUnits": v["cooledCapacityUnits"]}})
}
func check(w http.ResponseWriter, u map[string]any, r string, x map[string]any) {
	ok, reason, lab := service(x)
	d := map[string]any{"serviceable": ok, "reason": reason, "serviceabilityVersion": db.Revision}
	if ok {
		d["targetLaboratoryId"] = lab["locationId"]
		d["estimatedArrivalAt"] = now()
	}
	write(w, 200, map[string]any{"data": d})
}
func snapshot(w http.ResponseWriter, u map[string]any, r string) {
	regions := []any{}
	for _, l := range db.Locations {
		if l["active"] == true && has(arr(l["functions"]), "collection_point") {
			regions = append(regions, map[string]any{"locationId": l["locationId"], "coordinate": l["coordinate"], "coverageKm": l["coverageKm"]})
		}
	}
	write(w, 200, map[string]any{"data": map[string]any{"version": db.Revision, "status": "complete", "computedAt": now(), "networkRevision": db.Revision, "regions": regions, "activeCollectionPointCount": len(regions)}})
}
func createRequest(w http.ResponseWriter, u map[string]any, r string, x map[string]any, presealed bool) {
	if !require(w, u, r, "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team") {
		return
	}
	if presealed && str(x["originType"]) == "home" {
		err(w, 400, "invalid_origin", "Pre-sealed samples cannot originate at a home")
		return
	}
	ok, reason, lab := service(x)
	if !ok {
		err(w, 409, reason, "The request is not serviceable")
		return
	}
	sid, rid, jid := id(), id(), id()
	status := "planned"
	if presealed {
		status = "sealed"
	}
	s := map[string]any{"sampleId": sid, "requestId": rid, "requesterId": u["userId"], "origin": x["origin"], "originType": x["originType"], "requestedAt": x["requestedAt"], "deliveryDeadline": x["deliveryDeadline"], "earliestCollectionAt": x["earliestCollectionAt"], "latestCollectionAt": x["latestCollectionAt"], "sampleTypeId": x["sampleTypeId"], "containerType": x["containerType"], "temperatureMinC": x["temperatureMinC"], "temperatureMaxC": x["temperatureMaxC"], "incompatibleSampleTypes": arr(x["incompatibleSampleTypes"]), "serviceability": "serviceable", "status": status, "sealed": presealed, "timeline": timeline(status), "activeJourneyId": jid, "targetLaboratoryId": lab["locationId"], "locationStale": false}
	if presealed {
		s["currentHolderId"] = u["userId"]
	}
	db.Samples[sid] = s
	j := map[string]any{"journeyId": jid, "sampleIds": []any{sid}, "status": "active", "routeMode": "direct", "planVersion": 1, "targetLaboratoryId": lab["locationId"], "estimatedDeliveryAt": x["deliveryDeadline"], "legs": []any{}, "history": timeline("planned")}
	db.Journeys[jid] = j
	kind := "collection"
	if presealed {
		kind = "transport"
	}
	aid := id()
	a := map[string]any{"assignmentId": aid, "sampleId": sid, "journeyId": jid, "kind": kind, "status": "offered", "sequence": 1, "toLocationId": lab["locationId"], "history": timeline("offered")}
	db.Assignments[aid] = a
	s["activeAssignmentIds"] = []any{aid}
	audit(u, r, "create_request", "sample", sid, true, s)
	write(w, 201, map[string]any{"data": map[string]any{"requestId": rid, "sampleId": sid, "journeyId": jid, "serviceability": "serviceable", "status": status, "targetLaboratoryId": lab["locationId"]}})
}
func roleWork(w http.ResponseWriter, u map[string]any, r string, x map[string]any) {
	out := map[string]any{"pending": []any{}, "inProgress": []any{}, "completed": []any{}}
	if r == "requester" {
		for _, s := range db.Samples {
			if str(s["requesterId"]) == str(u["userId"]) {
				bucket := "inProgress"
				if str(s["status"]) == "received" {
					bucket = "completed"
				}
				out[bucket] = append(arr(out[bucket]), sampleItem(s))
			}
		}
	} else {
		for _, a := range db.Assignments {
			if str(a["workerId"]) == str(u["userId"]) {
				bucket := "pending"
				if str(a["status"]) == "accepted" || str(a["status"]) == "in_progress" {
					bucket = "inProgress"
				}
				if str(a["status"]) == "completed" {
					bucket = "completed"
				}
				out[bucket] = append(arr(out[bucket]), assignmentItem(a))
			}
		}
	}
	write(w, 200, map[string]any{"data": out})
}
func sampleItem(s map[string]any) map[string]any {
	return map[string]any{"kind": "sample", "sampleId": s["sampleId"], "requestId": s["requestId"], "status": s["status"], "history": s["timeline"], "locationStale": s["locationStale"], "deliveryDeadline": s["deliveryDeadline"], "currentHolderId": s["currentHolderId"], "activeJourneyId": s["activeJourneyId"]}
}
func assignmentItem(a map[string]any) map[string]any {
	return map[string]any{"kind": a["kind"], "assignmentId": a["assignmentId"], "sampleId": a["sampleId"], "status": a["status"], "history": a["history"], "journeyId": a["journeyId"], "sequence": a["sequence"], "toLocationId": a["toLocationId"]}
}
func sampleState(w http.ResponseWriter, u map[string]any, r, sid string) {
	s := db.Samples[sid]
	if s == nil {
		err(w, 404, "not_found", "Sample not found")
		return
	}
	if r == "requester" && str(s["requesterId"]) != str(u["userId"]) {
		err(w, 403, "forbidden", "Sample is not yours")
		return
	}
	d := map[string]any{"sampleId": s["sampleId"], "requestId": s["requestId"], "requesterId": s["requesterId"], "origin": s["origin"], "originType": s["originType"], "requestedAt": s["requestedAt"], "deliveryDeadline": s["deliveryDeadline"], "sampleTypeId": s["sampleTypeId"], "containerType": s["containerType"], "temperatureMinC": s["temperatureMinC"], "temperatureMaxC": s["temperatureMaxC"], "incompatibleSampleTypes": s["incompatibleSampleTypes"], "serviceability": s["serviceability"], "activeAssignmentIds": s["activeAssignmentIds"], "state": map[string]any{"status": s["status"]}, "timeline": s["timeline"], "activeJourneyId": s["activeJourneyId"], "targetLaboratoryId": s["targetLaboratoryId"], "currentHolderId": s["currentHolderId"], "latestLocation": s["latestLocation"], "locationRecordedAt": s["locationRecordedAt"], "locationStale": s["locationStale"]}
	for k, v := range d {
		if v == nil {
			delete(d, k)
		}
	}
	write(w, 200, map[string]any{"data": d})
}
func lifecycle(w http.ResponseWriter, u map[string]any, r string, x map[string]any) {
	s := db.Samples[str(x["sampleId"])]
	if s == nil {
		err(w, 404, "not_found", "Sample not found")
		return
	}
	d := map[string]any{"sampleId": s["sampleId"], "status": s["status"], "sealed": s["sealed"], "completedLegIds": []any{}, "activeReplacementPlanIds": []any{}, "timeline": s["timeline"], "activeJourneyId": s["activeJourneyId"], "currentHolderId": s["currentHolderId"], "pendingHandoffId": s["pendingHandoffId"], "latestLocation": s["latestLocation"], "locationRecordedAt": s["locationRecordedAt"], "locationStale": s["locationStale"]}
	for k, v := range d {
		if v == nil {
			delete(d, k)
		}
	}
	write(w, 200, map[string]any{"data": d})
}
func plan(w http.ResponseWriter, u map[string]any, r string, x map[string]any) {
	j := db.Journeys[str(x["journeyId"])]
	if j == nil {
		err(w, 404, "not_found", "Journey not found")
		return
	}
	write(w, 200, map[string]any{"data": j})
}
func assignmentAction(w http.ResponseWriter, u map[string]any, r string, x map[string]any, p string) {
	a := db.Assignments[str(x["assignmentId"])]
	if a == nil {
		err(w, 404, "not_found", "Assignment not found")
		return
	}
	if p == "accept-assignment" {
		if str(a["status"]) != "offered" {
			err(w, 409, "offer_not_available", "Assignment offer is no longer available")
			return
		}
		a["workerId"] = u["userId"]
		a["status"] = "accepted"
		write(w, 201, map[string]any{"data": map[string]any{"assignmentId": a["assignmentId"], "workerId": u["userId"], "status": "accepted"}})
		return
	}
	if str(a["workerId"]) != str(u["userId"]) {
		err(w, 403, "forbidden", "Assignment belongs to another worker")
		return
	}
	if p == "decline-assignment" {
		a["status"] = "declined"
		write(w, 201, map[string]any{"data": map[string]any{"assignmentId": a["assignmentId"], "status": "declined"}})
		return
	}
	if p == "record-worker-location" {
		a["latestLocation"] = x["coordinate"]
		a["locationRecordedAt"] = x["recordedAt"]
		write(w, 201, map[string]any{"data": map[string]any{"assignmentId": a["assignmentId"], "coordinate": x["coordinate"], "sequence": x["sequence"], "recordedAt": x["recordedAt"]}})
		return
	}
	a["status"] = x["status"]
	a["history"] = append(arr(a["history"]), map[string]any{"status": x["status"], "occurredAt": x["occurredAt"]})
	write(w, 201, map[string]any{"data": map[string]any{"assignmentId": a["assignmentId"], "status": a["status"]}})
}
func seal(w http.ResponseWriter, u map[string]any, r string, x map[string]any) {
	if !require(w, u, r, "collection_professional") {
		return
	}
	s := db.Samples[str(x["sampleId"])]
	a := db.Assignments[str(x["assignmentId"])]
	if s == nil || a == nil {
		err(w, 404, "not_found", "Sample or assignment not found")
		return
	}
	if str(a["workerId"]) != str(u["userId"]) || str(a["status"]) != "accepted" {
		err(w, 409, "collection_not_ready", "Accept the collection assignment first")
		return
	}
	s["sealed"] = true
	s["status"] = "sealed"
	s["currentHolderId"] = u["userId"]
	s["sealedAt"] = x["collectedAt"]
	s["timeline"] = append(arr(s["timeline"]), map[string]any{"status": "sealed", "occurredAt": x["collectedAt"]})
	a["status"] = "completed"
	write(w, 201, map[string]any{"data": map[string]any{"sampleId": s["sampleId"], "status": "sealed", "currentHolderId": u["userId"], "sealedAt": x["collectedAt"], "handlingCompliant": true}})
}
func handoff(w http.ResponseWriter, u map[string]any, r string, x map[string]any, p string) {
	if p == "initiate-handoff" {
		s := db.Samples[str(x["sampleId"])]
		if s == nil {
			err(w, 404, "not_found", "Sample not found")
			return
		}
		if str(s["currentHolderId"]) != str(u["userId"]) {
			err(w, 403, "forbidden", "Only current holder can initiate handoff")
			return
		}
		h := map[string]any{"handoffId": id(), "sampleId": s["sampleId"], "senderId": u["userId"], "receiverId": x["receiverId"], "status": "pending", "senderConfirmed": true, "receiverConfirmed": false}
		db.Handoffs[str(h["handoffId"])] = h
		s["pendingHandoffId"] = h["handoffId"]
		write(w, 201, map[string]any{"data": map[string]any{"handoffId": h["handoffId"], "sampleId": s["sampleId"], "status": "pending", "currentHolderId": s["currentHolderId"]}})
		return
	}
	h := db.Handoffs[str(x["handoffId"])]
	if h == nil {
		err(w, 404, "not_found", "Handoff not found")
		return
	}
	if str(x["confirmationSide"]) == "receiver" && str(h["receiverId"]) == str(u["userId"]) {
		h["receiverConfirmed"] = true
	}
	done, _ := h["senderConfirmed"].(bool)
	recv, _ := h["receiverConfirmed"].(bool)
	if done && recv {
		h["status"] = "completed"
		s := db.Samples[str(h["sampleId"])]
		s["currentHolderId"] = h["receiverId"]
		delete(s, "pendingHandoffId")
	}
	write(w, 201, map[string]any{"data": map[string]any{"handoffId": h["handoffId"], "status": h["status"], "currentHolderId": db.Samples[str(h["sampleId"])]["currentHolderId"]}})
}
func sampleAction(w http.ResponseWriter, u map[string]any, r string, x map[string]any, p string) {
	s := db.Samples[str(x["sampleId"])]
	if s == nil {
		err(w, 404, "not_found", "Sample not found")
		return
	}
	if p == "confirm-laboratory-receipt" {
		if !require(w, u, r, "laboratory_team") {
			return
		}
		s["status"] = "received"
		s["receivedLaboratoryId"] = x["laboratoryId"]
		s["timeline"] = append(arr(s["timeline"]), map[string]any{"status": "received", "occurredAt": x["receivedAt"]})
		write(w, 201, map[string]any{"data": map[string]any{"sampleId": s["sampleId"], "status": "received", "receivedAt": x["receivedAt"], "laboratoryId": x["laboratoryId"]}})
		return
	}
	if p == "record-laboratory-exception" {
		s["status"] = "exception"
		write(w, 201, map[string]any{"data": map[string]any{"exceptionId": id(), "sampleId": s["sampleId"], "status": "exception", "reason": x["reason"]}})
		return
	}
	lo, _ := x["observedTemperatureC"].(float64)
	min, _ := s["temperatureMinC"].(float64)
	max, _ := s["temperatureMaxC"].(float64)
	good := lo >= min && lo <= max && str(x["containerType"]) == str(s["containerType"])
	if !good {
		s["status"] = "exception"
	}
	write(w, 201, map[string]any{"data": map[string]any{"checkpointId": id(), "sampleId": s["sampleId"], "compliant": good, "sampleStatus": s["status"]}})
}
func operations(w http.ResponseWriter, u map[string]any, r string) {
	if !require(w, u, r, "dispatcher", "administrator") {
		return
	}
	ss, ws, ls, cs, ex := []any{}, []any{}, []any{}, []any{}, []any{}
	for _, s := range db.Samples {
		ss = append(ss, map[string]any{"sampleId": s["sampleId"], "status": s["status"], "locationStale": s["locationStale"]})
		if str(s["status"]) == "exception" {
			ex = append(ex, s)
		}
	}
	for _, v := range db.Users {
		ws = append(ws, map[string]any{"workerId": v["userId"], "available": v["available"], "status": "available", "capacityUnits": v["capacityUnits"], "assignmentCount": 0, "locationStale": false})
	}
	for _, v := range db.Locations {
		ls = append(ls, v)
	}
	for _, v := range db.Connections {
		cs = append(cs, v)
	}
	write(w, 200, map[string]any{"data": map[string]any{"samples": ss, "workers": ws, "locations": ls, "connections": cs, "routes": []any{}, "handoffs": []any{}, "delays": []any{}, "exceptions": ex, "assignmentCountSpread": 0, "ineligibleAssignmentCount": 0}})
}
func searchAudit(w http.ResponseWriter, u map[string]any, r string, x map[string]any) {
	if !require(w, u, r, "dispatcher", "administrator") {
		return
	}
	out := []any{}
	for _, v := range db.Audit {
		out = append(out, v)
	}
	sort.Slice(out, func(i, j int) bool {
		return str(out[i].(map[string]any)["occurredAt"]) > str(out[j].(map[string]any)["occurredAt"])
	})
	write(w, 200, map[string]any{"data": map[string]any{"entries": out, "total": len(out), "returned": len(out), "offset": 0, "limit": len(out), "order": "newest_first", "hasMore": false}})
}
func planChange(w http.ResponseWriter, u map[string]any, r string, x map[string]any, p string) {
	if !require(w, u, r, "dispatcher", "administrator") {
		return
	}
	if p == "report-disruption" {
		write(w, 201, map[string]any{"data": map[string]any{"disruptionId": id(), "affectedSampleIds": []any{}, "replacementPlanIds": []any{}, "replanStatus": "not_required"}})
		return
	}
	j := db.Journeys[str(x["journeyId"])]
	if j == nil {
		err(w, 404, "not_found", "Journey not found")
		return
	}
	if p == "cancel-journey" {
		j["status"] = "cancelled"
		write(w, 201, map[string]any{"data": map[string]any{"journeyId": j["journeyId"], "status": "cancelled", "sampleIds": j["sampleIds"]}})
		return
	}
	pv, _ := j["planVersion"].(float64)
	j["planVersion"] = pv + 1
	write(w, 201, map[string]any{"data": j})
}
func readUser(w http.ResponseWriter, u map[string]any, r, uid string) {
	if uid != str(u["userId"]) && !require(w, u, r, "administrator", "dispatcher") {
		return
	}
	v := db.Users[uid]
	if v == nil {
		err(w, 404, "not_found", "User not found")
		return
	}
	write(w, 200, map[string]any{"data": map[string]any{"userId": v["userId"], "username": v["username"], "email": v["email"], "fullName": v["fullName"], "phone": v["phone"], "roles": v["roles"], "qualifications": v["qualifications"], "certifications": v["certifications"], "active": v["active"]}})
}
func bootstrap(w http.ResponseWriter, u map[string]any, r string) {
	requesterSamples := []any{}
	if r == "requester" {
		for _, s := range db.Samples {
			if str(s["requesterId"]) == str(u["userId"]) { requesterSamples = append(requesterSamples, sampleItem(s)) }
		}
	}
	write(w, 200, map[string]any{"data": map[string]any{
		"user": map[string]any{"userId": u["userId"], "username": u["username"], "fullName": u["fullName"], "roles": u["roles"], "activeRole": r, "roleSelectionRequired": false},
		"serverTime": now(), "requesterSamples": requesterSamples,
	}})
}

