package main

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"math"
	"net/http"
	"os"
	"sort"
	"strings"
	"sync"
	"time"
)

type Store struct {
	sync.Mutex
	Users       map[string]map[string]any `json:"users"`
	Sessions    map[string]string         `json:"sessions"`
	Locations   map[string]map[string]any `json:"locations"`
	Connections map[string]map[string]any `json:"connections"`
	Types       map[string]map[string]any `json:"types"`
	Samples     map[string]map[string]any `json:"samples"`
	Journeys    map[string]map[string]any `json:"journeys"`
	Assignments map[string]map[string]any `json:"assignments"`
	Handoffs    map[string]map[string]any `json:"handoffs"`
	Audit       []map[string]any          `json:"audit"`
	Revision    int                       `json:"revision"`
}

var db = &Store{}
var stateFile = "/workspace/.labflow-state.json"

func id() string {
	b := make([]byte, 16)
	rand.Read(b)
	return fmt.Sprintf("%s-%s-4%s-%s-%s", hex.EncodeToString(b[:4]), hex.EncodeToString(b[4:6]), hex.EncodeToString(b[6:8])[:3], hex.EncodeToString(b[8:10]), hex.EncodeToString(b[10:]))
}
func now() string { return time.Now().UTC().Format(time.RFC3339) }
func initStore() {
	db.Users = map[string]map[string]any{}
	db.Sessions = map[string]string{}
	db.Locations = map[string]map[string]any{}
	db.Connections = map[string]map[string]any{}
	db.Types = map[string]map[string]any{}
	db.Samples = map[string]map[string]any{}
	db.Journeys = map[string]map[string]any{}
	db.Assignments = map[string]map[string]any{}
	db.Handoffs = map[string]map[string]any{}
	db.Audit = []map[string]any{}
	db.Revision = 1
}
func load() {
	initStore()
	b, e := os.ReadFile(stateFile)
	if e == nil {
		json.Unmarshal(b, db)
	}
	if len(db.Users) == 0 {
		u := map[string]any{"userId": id(), "username": os.Getenv("ADMIN_USERNAME"), "password": os.Getenv("ADMIN_PASSWORD"), "roles": []any{"administrator", "dispatcher"}, "qualifications": []any{}, "certifications": []any{}, "active": true, "available": true, "capacityUnits": 10}
		if u["username"] == "" {
			u["username"] = "admin"
		}
		if u["password"] == "" {
			u["password"] = "admin"
		}
		db.Users[u["userId"].(string)] = u
	}
	seedTypes()
}
func seedTypes() {
	if len(db.Types) > 0 {
		return
	}
	for _, v := range []struct {
		name, container string
		min, max        float64
		cool, batch     bool
	}{{"Amber", "standard", 2, 25, false, true}, {"Indigo", "indigo", 2, 25, false, true}, {"Frost", "cooled", 2, 8, true, true}, {"Pulse", "priority", 2, 25, false, false}} {
		x := map[string]any{"sampleTypeId": id(), "name": v.name, "qualifiedCollectorRequired": true, "requiredQualification": v.name, "containerType": v.container, "temperatureMinC": v.min, "temperatureMaxC": v.max, "incompatibleSampleTypes": []any{}, "requiresCooledRoute": v.cool, "batchingAllowed": v.batch}
		db.Types[x["sampleTypeId"].(string)] = x
	}
}
func save() { b, _ := json.Marshal(db); os.WriteFile(stateFile, b, 0600) }
func write(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}
func err(w http.ResponseWriter, status int, code, msg string) {
	write(w, status, map[string]any{"error": msg, "code": code})
}
func body(r *http.Request) (map[string]any, bool) {
	var x map[string]any
	if json.NewDecoder(r.Body).Decode(&x) != nil {
		return nil, false
	}
	return x, true
}
func arr(v any) []any {
	if x, ok := v.([]any); ok {
		return x
	}
	return []any{}
}
func str(v any) string { x, _ := v.(string); return x }
func has(xs []any, x string) bool {
	for _, v := range xs {
		if str(v) == x {
			return true
		}
	}
	return false
}
func audit(user map[string]any, role, action, entityType, entityID string, success bool, changes any) {
	db.Audit = append(db.Audit, map[string]any{"auditId": id(), "actorId": user["userId"], "role": role, "action": action, "entityType": entityType, "entityId": entityID, "occurredAt": now(), "success": success, "changes": changes})
}
func auth(w http.ResponseWriter, r *http.Request) (map[string]any, string, bool) {
	token := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
	uid := db.Sessions[token]
	u := db.Users[uid]
	if u == nil || !u["active"].(bool) {
		err(w, 401, "unauthorized", "Authentication is required")
		return nil, "", false
	}
	role := r.Header.Get("X-Active-Role")
	if role == "" {
		role = str(u["activeRole"])
	}
	if role == "" || !has(arr(u["roles"]), role) {
		err(w, 409, "role_not_selected", "Select an assigned active role")
		return nil, "", false
	}
	return u, role, true
}
func require(w http.ResponseWriter, u map[string]any, role string, roles ...string) bool {
	for _, r := range roles {
		if role == r {
			return true
		}
	}
	err(w, 403, "forbidden", "This role cannot perform this action")
	return false
}
func timeline(status string) []any {
	return []any{map[string]any{"status": status, "occurredAt": now()}}
}
func coord(v any) map[string]any { x, _ := v.(map[string]any); return x }
func distance(a, b map[string]any) float64 {
	lat1, _ := a["latitude"].(float64)
	lon1, _ := a["longitude"].(float64)
	lat2, _ := b["latitude"].(float64)
	lon2, _ := b["longitude"].(float64)
	return math.Hypot((lat1-lat2)*111, (lon1-lon2)*75)
}
func acceptingLab(typeID string) (map[string]any, bool) {
	for _, l := range db.Locations {
		if l["active"] == true && has(arr(l["functions"]), "laboratory") && has(arr(l["acceptedSampleTypeIds"]), typeID) {
			return l, true
		}
	}
	return nil, false
}
func activeCollection(origin map[string]any) bool {
	for _, l := range db.Locations {
		if l["active"] == true && has(arr(l["functions"]), "collection_point") && distance(origin, coord(l["coordinate"])) <= 5 {
			return true
		}
	}
	return false
}
func service(x map[string]any) (bool, string, map[string]any) {
	if !activeCollection(coord(x["origin"])) {
		return false, "outside_service_coverage", nil
	}
	l, ok := acceptingLab(str(x["sampleTypeId"]))
	if !ok {
		return false, "no_accepting_laboratory", nil
	}
	return true, "serviceable", l
}
func main() {
	load()
	if len(os.Args) > 1 && os.Args[1] == "--reset" {
		save()
		return
	}
	defer save()
	mux := http.NewServeMux()
	mux.HandleFunc("/ready", func(w http.ResponseWriter, r *http.Request) { write(w, 200, map[string]string{"status": "ready"}) })
	mux.HandleFunc("/api/", api)
	mux.HandleFunc("/", web)
	log.Println("LabFlow listening at 127.0.0.1:8080")
	log.Fatal(http.ListenAndServe("127.0.0.1:8080", mux))
}
func web(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Write([]byte(indexHTML))
}
func api(w http.ResponseWriter, r *http.Request) {
	db.Lock()
	defer db.Unlock()
	p := strings.TrimPrefix(r.URL.Path, "/api/")
	if p == "authenticate-user" {
		login(w, r)
		return
	}
	if p == "events" {
		w.Header().Set("Content-Type", "text/event-stream")
		fmt.Fprint(w, "event: ready\ndata: {\"status\":\"connected\"}\n\n")
		return
	}
	u, role, ok := auth(w, r)
	if !ok {
		return
	}
	if p == "ui/bootstrap" && r.Method == "GET" {
		bootstrap(w, u, role)
		return
	}
	if strings.HasPrefix(p, "read-sample-state/") {
		sampleState(w, u, role, strings.TrimPrefix(p, "read-sample-state/"))
		return
	}
	if strings.HasPrefix(p, "read-user/") {
		readUser(w, u, role, strings.TrimPrefix(p, "read-user/"))
		return
	}
	x, valid := body(r)
	if !valid {
		err(w, 400, "invalid_json", "Invalid JSON body")
		return
	}
	switch p {
	case "select-active-role":
		selectRole(w, u, x)
	case "create-user":
		createUser(w, u, role, x)
	case "update-user-access":
		updateUser(w, u, role, x)
	case "create-sample-type":
		createType(w, u, role, x)
	case "update-sample-type":
		updateType(w, u, role, x)
	case "create-location":
		createLocation(w, u, role, x)
	case "update-location":
		updateLocation(w, u, role, x)
	case "create-connection":
		createConnection(w, u, role, x)
	case "set-location-status", "set-location-function-status", "set-connection-status", "configure-capacity", "configure-laboratory-acceptance", "set-worker-availability":
		adminChange(w, u, role, x, p)
	case "check-serviceability":
		check(w, u, role, x)
	case "read-serviceability-snapshot":
		snapshot(w, u, role)
	case "create-collection-request", "ingest-presealed-sample":
		createRequest(w, u, role, x, p == "ingest-presealed-sample")
	case "list-role-work":
		roleWork(w, u, role, x)
	case "read-sample-lifecycle":
		lifecycle(w, u, role, x)
	case "read-operations-state":
		operations(w, u, role)
	case "read-journey-plan":
		plan(w, u, role, x)
	case "accept-assignment", "decline-assignment", "update-assignment-progress", "record-worker-location":
		assignmentAction(w, u, role, x, p)
	case "collect-and-seal-sample":
		seal(w, u, role, x)
	case "initiate-handoff", "confirm-handoff":
		handoff(w, u, role, x, p)
	case "confirm-laboratory-receipt", "record-laboratory-exception", "record-handling-checkpoint":
		sampleAction(w, u, role, x, p)
	case "search-audit-trail":
		searchAudit(w, u, role, x)
	case "cancel-journey", "reroute-journey", "split-journey", "merge-journeys", "edit-active-plan", "report-disruption":
		planChange(w, u, role, x, p)
	default:
		err(w, 404, "not_found", "Unknown API operation")
	}
	save()
}
func login(w http.ResponseWriter, r *http.Request) {
	x, ok := body(r)
	if !ok {
		err(w, 400, "invalid_json", "Invalid JSON body")
		return
	}
	for _, u := range db.Users {
		if str(u["username"]) == str(x["username"]) && str(u["password"]) == str(x["password"]) && u["active"] == true {
			t := id()
			db.Sessions[t] = str(u["userId"])
			roles := arr(u["roles"])
			active := str(u["activeRole"])
			if active == "" {
				active = str(roles[0])
				u["activeRole"] = active
			}
			audit(u, active, "sign_in", "user", str(u["userId"]), true, nil)
			write(w, 200, map[string]any{"data": map[string]any{"sessionToken": t, "userId": u["userId"], "roles": roles, "activeRole": active}})
			return
		}
	}
	err(w, 401, "invalid_credentials", "Username or password is incorrect")
}
func selectRole(w http.ResponseWriter, u map[string]any, x map[string]any) {
	r := str(x["role"])
	if !has(arr(u["roles"]), r) {
		err(w, 403, "forbidden", "Role is not assigned")
		return
	}
	u["activeRole"] = r
	write(w, 200, map[string]any{"data": map[string]any{"userId": u["userId"], "activeRole": r}})
}
func createUser(w http.ResponseWriter, actor map[string]any, role string, x map[string]any) {
	if !require(w, actor, role, "administrator") {
		return
	}
	for _, u := range db.Users {
		if str(u["username"]) == str(x["username"]) {
			err(w, 409, "conflict", "Username already exists")
			return
		}
	}
	v := map[string]any{"userId": id(), "username": x["username"], "password": x["initialPassword"], "roles": arr(x["roles"]), "qualifications": arr(x["qualifications"]), "certifications": arr(x["certifications"]), "active": x["active"], "email": x["email"], "fullName": x["fullName"], "phone": x["phone"], "assignedLocationId": x["assignedLocationId"], "available": true, "capacityUnits": 10}
	db.Users[str(v["userId"])] = v
	audit(actor, role, "create_user", "user", str(v["userId"]), true, v)
	write(w, 201, map[string]any{"data": map[string]any{"userId": v["userId"], "username": v["username"]}})
}
