elected':'')+'>'+x+'</option>').join('')+'</select> <button onclick="logout()">Sign out</button>';let w=await api('list-role-work',{});app.innerHTML='<div class=card><h1>My work</h1><p>Working as <span class=badge>'+user.activeRole+'</span></p><h2>Current</h2>'+table((w.data.pending||[]).concat(w.data.inProgress||[]))+'<h2>Completed</h2>'+table(w.data.completed||[])+'</div><div class=card><h2>Serviceability check</h2><p class=muted>Dry run only — no samples or reservations are created.</p><button onclick="showRequest()">Create collection request</button></div>'}function table(rows){return rows.length?'<table><tr><th>Work</th><th>Status</th><th>Timeline</th></tr>'+rows.map(x=>'<tr><td>'+ (x.sampleId||x.assignmentId||x.journeyId)+'</td><td>'+x.status+'</td><td>'+((x.history||[]).map(h=>h.status).join(' → '))+'</td></tr>').join('')+'</table>':'<p class=muted>No work in this category.</p>'}function showRequest(){app.innerHTML='<div class=card><h1>New collection request</h1><p>Network setup is required before serviceability can succeed.</p><button onclick="home()">Back to work</button></div>'}async function switchRole(role){await api('select-active-role',{role});user.activeRole=role;home()}function logout(){token='';user=null;identity.textContent='';login()}const app=document.querySelector('#app');login()</script></main></body></html>`

