func adminChange(w http.ResponseWriter, a map[string]any, r string, x map[string]any, p string) {
	if p == "configure-capacity" && (r == "node_handler" || r == "laboratory_team") {
	} else if !require(w, a, r, "administrator") {
		return
	}
	var v map[string]any
	switch p {
	case "set-location-status":
		v = db.Locations[str(x["locationId"])]
		if v != nil {
			v["active"] = x["active"]
		}
	case "set-location-function-status":
		v = db.Locations[str(x["locationId"])]
		if v != nil {
			fs := arr(v["functions"])
			f := str(x["function"])
			on, _ := x["active"].(bool)
			if on && !has(fs, f) {
				fs = append(fs, f)
			}
			if !on {
				n := []any{}
				for _, q := range fs {
					if str(q) != f {
						n = append(n, q)
					}
				}
				fs = n
			}
			v["functions"] = fs
		}
	case "set-connection-status":
		v = db.Connections[str(x["connectionId"])]
		if v != nil {
			v["active"] = x["active"]
		}
	case "configure-capacity":
		v = db.Locations[str(x["resourceId"])]
		if v == nil {
			v = db.Connections[str(x["resourceId"])]
		}
		if v != nil {
			v["capacityUnits"] = x["capacityUnits"]
			v["cooledCapacityUnits"] = x["cooledCapacityUnits"]
		}
	case "configure-laboratory-acceptance":
		v = db.Locations[str(x["laboratoryId"])]
		if v != nil {
			ss := arr(v["acceptedSampleTypeIds"])
			if b, _ := x["accepts"].(bool); b && !has(ss, str(x["sampleTypeId"])) {
				ss = append(ss, x["sampleTypeId"])
			}
			v["acceptedSampleTypeIds"] = ss
			write(w, 200, map[string]any{"data": map[string]any{"acceptanceId": id(), "accepts": x["accepts"]}})
			return
		}
	case "set-worker-availability":
		v = db.Users[str(x["workerId"])]
		if v != nil {
			v["available"] = x["available"]
			v["capacityUnits"] = x["capacityUnits"]
		}
	}
	if v == nil {
		err(w, 404, "not_found", "Resource not found")
		return
	}
	db.Revision++
	write(w, 200, map[string]any{"data": map[string]any{"resourceId": x["resourceId"], "capacityUnits": v["capacityUnits"], "cooledCapacityUnits": v["cooledCapacityUnits"]}})
}
