import { useEffect, useState } from 'react';

type Work = { sampleId?: string; assignmentId?: string; status: string };
type Bootstrap = { user: { username: string; activeRole: string; roles: string[] } };

export function App({ token }: { token: string }) {
  const [bootstrap, setBootstrap] = useState<Bootstrap | null>(null);
  const [work, setWork] = useState<Work[]>([]);

  useEffect(() => {
    const headers = { Authorization: `Bearer ${token}` };
    Promise.all([
      fetch('/api/ui/bootstrap', { headers }).then((r) => r.json()),
      fetch('/api/list-role-work', { method: 'POST', headers: { ...headers, 'Content-Type': 'application/json' }, body: '{}' }).then((r) => r.json()),
    ]).then(([user, roleWork]) => {
      setBootstrap(user.data);
      setWork([...(roleWork.data.pending ?? []), ...(roleWork.data.inProgress ?? [])]);
    });
  }, [token]);

  if (!bootstrap) return <p>Loading operational workspace…</p>;
  return <main><h1>My work</h1><p>Working as {bootstrap.user.activeRole}</p><ul>{work.map((item) => <li key={item.sampleId ?? item.assignmentId}>{item.status}</li>)}</ul></main>;
}

